import java.util.Deque;
import java.util.ArrayDeque;

public class TrappingRainWater {

    // 解法一：双指针 O(1) 空间（面试首选）
    public int trap(int[] height) {
        int left = 0, right = height.length - 1;
        int leftMax = 0, rightMax = 0, water = 0;
        while (left < right) {
            leftMax = Math.max(leftMax, height[left]);   // 先更新再结算
            rightMax = Math.max(rightMax, height[right]);
            if (leftMax <= rightMax) {
                water += leftMax - height[left];  // leftMax 是较小侧，水位上限已确定
                left++;
            } else {
                water += rightMax - height[right];
                right--;
            }
        }
        return water;
    }

    // 解法二：单调栈按层结算
    public int trapStack(int[] height) {
        Deque<Integer> stack = new ArrayDeque<>();
        int water = 0;
        for (int i = 0; i < height.length; i++) {
            while (!stack.isEmpty() && height[i] > height[stack.peek()]) {
                int bottom = stack.pop();         // 槽底
                if (stack.isEmpty()) break;       // 无左墙，无法接水
                int left = stack.peek();
                int width = i - left - 1;         // 左右墙之间距离
                int h = Math.min(height[i], height[left]) - height[bottom];
                water += width * h;
            }
            stack.push(i);
        }
        return water;
    }

    // 解法三：DP 预计算（理解用，面试一般不首选）
    public int trapDP(int[] height) {
        int n = height.length;
        if (n < 3) return 0;
        int[] leftMax = new int[n];
        int[] rightMax = new int[n];
        leftMax[0] = height[0];
        for (int i = 1; i < n; i++) leftMax[i] = Math.max(leftMax[i - 1], height[i]);
        rightMax[n - 1] = height[n - 1];
        for (int i = n - 2; i >= 0; i--) rightMax[i] = Math.max(rightMax[i + 1], height[i]);
        int water = 0;
        for (int i = 0; i < n; i++) water += Math.min(leftMax[i], rightMax[i]) - height[i];
        return water;
    }
}
